function method(k){return METHODS.find(m=>m.key===k)}
function head(title,desc,extra=''){return '<div class="pagehead"><div><div class="caps">Six Sigma Studio</div><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div><div class="buttons">'+extra+'</div></div>'}
