function render(){if(!S.user){authView();return}let page=S.page;if(page!=='projects'&&!S.project){page='projects';S.page=page}let inner=page==='projects'?projectPage():page==='overview'?overview():P.includes(page)?phasePage(page):page==='data'?dataPage():page==='kpis'?kpiPage():page==='actions'?actionPage():page==='files'?filePage():reportPage();shell(inner)}
function authView(message=''){ $('#app').innerHTML='<div class="auth"><div class="card"><div class="caps">Secure workspace</div><h1>Six Sigma Studio</h1><p class="muted">Sign in to access your private Six Sigma projects and their saved data.</p><form id="auth-form"><label>Email</label><input type="email" name="email" required autocomplete="email"><label>Password</label><input type="password" name="password" required minlength="6" autocomplete="current-password"><div class="buttons"><button class="btn primary" name="mode" value="login">Sign in</button><button class="btn" name="mode" value="signup">Create account</button></div></form><p class="small muted">'+esc(message)+'</p><p class="tiny muted">If email confirmation is enabled, check your inbox before signing in. Project data is protected by owner-based row-level security.</p></div></div>'}
async function request(table,op,args){let r;if(op==='read')r=await db.from(A[table]).select('*').eq('project_id',S.project.id).order('created_at',{ascending:true}).limit(5000);else if(op==='insert')r=await db.from(A[table]).insert(args).select().single();else if(op==='update')r=await db.from(A[table]).update(args.data).eq('id',args.id).eq('project_id',S.project.id).select().single();else if(op==='delete')r=await db.from(A[table]).delete().eq('id',args.id).eq('project_id',S.project.id);if(r.error)throw r.error;return r.data}
async function loadProjects(){const r=await db.from(A.projects).select('*').order('created_at',{ascending:false});if(r.error)throw r.error;S.projects=r.data||[];if(S.project){S.project=S.projects.find(p=>p.id===S.project.id)||null}if(!S.project&&S.projects.length)S.project=S.projects[0]}
async function loadProject(){if(!S.project)return;const tables=['phases','kpis','datasets','tools','actions','files'];const rs=await Promise.all(tables.map(t=>request(t,'read')));tables.forEach((t,i)=>S[t]=rs[i]);if(S.dataset&&!S.datasets.some(x=>x.id===S.dataset.id))S.dataset=null;if(S.tool&&!S.tools.some(x=>x.id===S.tool.id))S.tool=null;await loadRows()}
async function loadRows(){if(!S.project)return;let r=await db.from(A.rows).select('*').eq('project_id',S.project.id).order('sequence_no',{ascending:true}).limit(5000);if(r.error)throw r.error;S.rows=r.data||[]}
function projectPage(){return head('Project Command Center','Continue an existing project or create a new one.',btn('+ New project','new-project','primary'))+'<div class="grid cols3">'+S.projects.map(p=>'<div class="card projectbox" data-open-project="'+p.id+'"><div class="row">'+badge(p.methodology||'DMAIC')+'<span class="tiny muted">'+date(p.created_at)+'</span></div><h3>'+esc(p.name)+'</h3><p class="muted small">'+esc((p.objective||'No objective yet').slice(0,170))+'</p><p class="small">📍 '+esc(p.location||'Location not defined')+'</p>'+btn('Open project →','open:'+p.id,'primary')+'</div>').join('')+'</div>'+(S.projects.length?'':'<div class="empty">No projects yet. Create your first improvement project.</div>')}
