function closeModal(){let root=$('#modal-root');if(root)root.innerHTML=''}
function projectForm(p){p=p||{};modal('<h2>'+(p.id?'Edit project':'Create project')+'</h2><form id="project-form" data-id="'+esc(p.id||'')+'"><div class="formgrid">'+input('Project name','name',p.name||'')+input('Location / site','location',p.location||'')+input('Project leader','leader',p.leader||'')+input('Sponsor','sponsor',p.sponsor||'')+select('Methodology','methodology',['DMAIC','PDCA','A3','Kaizen','Quick Win'].map(x=>[x,x]),p.methodology||'DMAIC')+'<div class="wide">'+input('Objective / business case','objective',p.objective||'','textarea')+'</div></div><div class="buttons section"><button class="btn primary" type="submit">Save project</button></div></form>')}
function kpiForm(k){k=k||{};modal('<h2>'+(k.id?'Edit KPI':'New KPI')+'</h2><form id="kpi-form" data-id="'+esc(k.id||'')+'"><div class="formgrid">'+input('KPI name','name',k.name||'')+input('Category','category',k.category||'Quality')+input('Unit','unit',k.unit||'')+select('Target rule','direction',[['at_most','Must not exceed (≤)'],['at_least','Must reach at least (≥)'],['range','Must stay in range']],k.direction||'at_most')+input('Baseline','baseline',k.baseline??'','number')+input('Target / lower bound','target_value',k.target_value??'','number')+input('Upper bound (for range)','target_high',k.target_high??'','number')+input('Source system or owner','source',k.source||'')+select('Link to dataset (optional)','dataset_id',[['','No dataset'],...S.datasets.map(d=>[d.id,d.name])],k.dataset_id||'')+select('Column containing measured values','value_field',[['','No linked measurement'],...S.datasets.flatMap(d=>d.columns.map(c=>[c.key,d.name+' · '+c.label]))],k.value_field||'')+'</div><div class="section"><button class="btn primary">Save KPI</button></div></form>')}
function datasetForm(){modal('<h2>Create dataset</h2><form id="dataset-form">'+input('Dataset name','name','Process measurements')+input('Description','description','')+'<p class="notice">Start with Date, Category and Value columns. Add as many custom columns as needed afterward.</p><div class="section"><button class="btn primary">Create dataset</button></div></form>')}
function actionForm(a){a=a||{};modal('<h2>'+(a.id?'Edit action':'Create action')+'</h2><form id="action-form" data-id="'+esc(a.id||'')+'"><div class="formgrid">'+input('Action title','title',a.title||'')+input('Owner','owner_name',a.owner_name||'')+input('Due date','due_date',a.due_date||'','date')+select('Phase','phase',P.map(p=>[p,p]),a.phase||S.phase)+select('Status','status',[['todo','To do'],['doing','In progress'],['done','Done']],a.status||'todo')+select('Related method / evidence','tool_id',[['','Not linked'],...S.tools.map(t=>[t.id,t.phase+' · '+t.title])],a.tool_id||'')+select('Priority','priority',[['low','Low'],['medium','Medium'],['high','High']],a.priority||'medium')+'<div class="wide">'+input('Notes / evidence','notes',a.notes||'','textarea')+'</div></div><div class="section"><button class="btn primary">Save action</button></div></form>')}
function fileModal(){modal('<h2>Upload project file</h2><form id="file-form">'+input('Description','title','')+'<div class="field"><label>File (max 10 MB)</label><input type="file" name="file" required></div><div class="section"><button class="btn primary">Upload to private storage</button></div></form>')}
async function persistTool(status){if(!S.tool)return;let updates={content:S.editor||{},conclusion:$('#tool-conclusion')?.value||'',status:status||S.tool.status};let t=await request('tools','update',{id:S.tool.id,data:updates});S.tool=t;S.tools=S.tools.map(a=>a.id===t.id?t:a);S.editor=structuredClone(t.content);note('Tool saved to Supabase');render()}
async function runCalc(){if(!S.tool)return;let c=S.editor||{};let ds=S.datasets.find(d=>d.id===c.dataset_id);if(!ds)throw Error('Select a saved dataset. Each analysis must explicitly name its source table.');let policy=methodPolicy(S.tool.method_key);if(policy){for(const [field,label,type] of policy.roles){if(!type.endsWith('?')&&!c[field])throw Error('Select '+label+' before calculating.');}}let source=S.rows.filter(r=>r.dataset_id===ds.id);if(!source.length)throw Error('The chosen data table has no saved observations. Add observations in Data Library.');if(c.order)source.sort((a,b)=>String(a.values[c.order]??'').localeCompare(String(b.values[c.order]??''),undefined,{numeric:true}));let res=isSPC(S.tool.method_key)?computeSPC(S.tool.method_key,source,c):calculate(S.tool.method_key,source,c);let t=await request('tools','update',{id:S.tool.id,data:{dataset_id:ds.id,content:c,result:res,conclusion:$('#tool-conclusion')?.value||'',status:'completed'}});S.tool=t;S.tools=S.tools.map(a=>a.id===t.id?t:a);S.editor=structuredClone(t.content);note('Calculation and inputs saved');render()}
function csvFromDataset(ds){let rs=S.rows.filter(r=>r.dataset_id===ds.id),cols=ds.columns;return csvSerialize([cols.map(c=>c.label),...rs.map(r=>cols.map(c=>r.values[c.key]))])}
async function importCSV(file,ds){
 let rows=parseCSV(await file.text());if(rows.length<2)throw Error('CSV must have a header and at least one data row.');
 let headers=rows.shift().map((h,i)=>h.trim()||'Column '+(i+1));
 if(new Set(headers.map(h=>h.toLowerCase())).size!==headers.length)throw Error('CSV column headers must be unique.');
 if(rows.length>5000)throw Error('This version imports up to 5,000 rows at once. Split this CSV to avoid incomplete imports.');
 let cols,sourceRows=rows;
 if(ds){
  const indexes=ds.columns.map(c=>headers.indexOf(c.label));if(indexes.some(i=>i<0))throw Error('The CSV must contain all columns of the selected saved table, matched by title.');
  cols=ds.columns;sourceRows=rows.map(r=>indexes.map(i=>r[i]??''));
 }else{
  cols=headers.map((label,i)=>({key:'csv_'+i,label,type:suggestColumnType(rows.slice(0,80).map(r=>r[i])),required:false,unit:''}));
 }
 const values=sourceRows.map((r,ri)=>Object.fromEntries(cols.map((c,i)=>{try{return [c.key,parseTypedValue(r[i]??'',c)]}catch(err){throw Error('CSV row '+(ri+2)+': '+err.message)}})));
 if(!ds)ds=await request('datasets','insert',{project_id:S.project.id,name:file.name.replace(/\.csv$/i,''),columns:cols,metadata:{origin:'csv',filename:file.name}});
 let payload=values.map(v=>({project_id:S.project.id,dataset_id:ds.id,values:v}));
 for(let i=0;i<payload.length;i+=200){let r=await db.from(A.rows).insert(payload.slice(i,i+200));if(r.error)throw r.error}
 S.dataset=ds;await loadProject();S.page='data';note(payload.length+' typed CSV observations stored in Data Library');render()
}
function reportHtml(){let body='<h1>'+esc(S.project.name)+'</h1><p><b>Objective:</b> '+esc(S.project.objective)+'</p><p><b>Location:</b> '+esc(S.project.location)+'</p>';for(let p of P){body+='<h2>'+esc(p)+'</h2><p>'+esc(S.phases.find(a=>a.phase===p)?.conclusion||'')+'</p>';for(let t of S.tools.filter(x=>x.phase===p)){body+='<h3>'+esc(t.title)+'</h3><p>'+esc(t.conclusion)+'</p><pre>'+esc(JSON.stringify(t.result?.metrics||t.content,null,2))+'</pre>'}}return '<!doctype html><html><head><meta charset="utf-8"><title>'+esc(S.project.name)+'</title><style>body{font:15px/1.5 Arial;max-width:860px;margin:50px auto;color:#15263f}h2{color:#315fb3;border-bottom:1px solid #ddd}pre{white-space:pre-wrap;background:#f7f9fc;padding:12px}</style></head><body>'+body+'</body></html>'}
async function refresh(){await loadProjects();await loadProject();render()}
async function command(code){
 if(busy)return;
 if(code==='new-project')return projectForm();
 if(code==='edit-project')return projectForm(S.project);
 if(code==='new-kpi')return kpiForm();
 if(code.startsWith('edit-kpi:'))return kpiForm(S.kpis.find(k=>k.id===code.slice(9)));
 if(code==='new-dataset')return openBuilder({S,modal,btn,request,loadProject,render,note,closeModal},null,null);
 if(code==='edit-schema')return openBuilder({S,modal,btn,request,loadProject,render,note,closeModal},S.dataset||S.datasets[0]);
 if(code.startsWith('template-dataset:'))return openBuilder({S,modal,btn,request,loadProject,render,note,closeModal},null,code.slice(17));
 if(code.startsWith('builder-'))return handleBuilderAction(code,{S,modal,btn,request,loadProject,render,note,closeModal});
 if(code==='open-data-from-tool'){if(S.tool?.id&&S.editor?.dataset_id){S.dataset=S.datasets.find(d=>d.id===S.editor.dataset_id)||null}S.page='data';return render()}
 if(code==='new-action')return actionForm();
 if(code.startsWith('edit-action:'))return actionForm(S.actions.find(a=>a.id===code.slice(12)));
 if(code==='upload-file')return fileModal();
 if(code==='close-modal')return closeModal();
 if(code==='logout'){await db.auth.signOut();S.user=null;S.project=null;authView();return}
 if(code==='go-report'){S.page='report';return render()}
 if(code==='go-data'){S.page='data';S.tool=null;return render()}
 if(code.startsWith('open:')){S.project=S.projects.find(p=>p.id===code.slice(5));S.page='overview';S.tool=null;await loadProject();return render()}
 if(code.startsWith('tool:')){S.tool=S.tools.find(t=>t.id===code.slice(5));S.editor=structuredClone(S.tool.content||{});S.page=S.tool.phase;return render()}
 if(code.startsWith('add-tool:')){let m=method(code.slice(9));let t=await request('tools','insert',{project_id:S.project.id,phase:m.phase,method_key:m.key,title:m.title,content:m.kind==='table'?{rows:[]}:m.kind==='form'?{fields:{}}:{}});S.tools.push(t);S.tool=t;S.editor=structuredClone(t.content);S.page=m.phase;note('New method instance created');return render()}
 if(code==='close-tool'){S.tool=null;S.editor=null;return render()}
 if(code.startsWith('delete-tool:')){let id=code.slice(12);if(!confirm('Delete this method instance and saved results?'))return;await request('tools','delete',{id});S.tools=S.tools.filter(t=>t.id!==id);S.tool=null;S.editor=null;return render()}
 if(code==='add-workbook-row'){let m=method(S.tool.method_key);(S.editor.rows??=[]).push(Object.fromEntries(m.columns.map(f=>[f.key,''])));return render()}
 if(code.startsWith('remove-row:')){S.editor.rows.splice(Number(code.slice(11)),1);return render()}
 if(code==='save-tool')return persistTool();
 if(code==='complete-tool')return persistTool(S.tool.status==='completed'?'draft':'completed');
 if(code==='calculate')return runCalc();
 if(code==='export-tool')return blobDownload(slug(S.tool.title)+'.json',JSON.stringify({project:S.project.name,tool:S.tool},null,2),'application/json');
 if(code==='save-phase'||code==='toggle-phase'){let phase=S.phases.find(r=>r.phase===S.page),conclusion=$('#phase-conclusion')?.value.trim()||'';if(code==='toggle-phase'&&!conclusion)throw Error('Write a phase conclusion before completing or reopening.');let status=code==='toggle-phase'?(phase?.status==='completed'?'in_progress':'completed'):(phase?.status||'in_progress'),data={conclusion,status,completed_at:status==='completed'?new Date().toISOString():null};if(phase)await request('phases','update',{id:phase.id,data});else await request('phases','insert',{project_id:S.project.id,phase:S.page,...data});await loadProject();note(status==='completed'?'Phase marked completed':'Phase conclusion saved');return render()}
 if(code==='add-column')return openBuilder({S,modal,btn,request,loadProject,render,note,closeModal},S.dataset||S.datasets[0]);
 if(code==='add-data-row'){let ds=S.dataset||S.datasets[0];if(!ds)throw Error('Create a dataset first.');let values=rowFromInputs(ds,'[data-new-cell]');if(Object.values(values).every(v=>v===null||v===''))throw Error('Enter at least one cell before saving.');let r=await db.from(A.rows).insert({dataset_id:ds.id,project_id:S.project.id,values});if(r.error)throw r.error;await loadRows();note('Typed observation saved to Supabase');return render()}
 if(code.startsWith('open-dataset:')){S.dataset=S.datasets.find(d=>d.id===code.slice(13));return render()}
 if(code.startsWith('delete-data-row:')){if(!confirm('Delete this observation?'))return;let r=await db.from(A.rows).delete().eq('id',code.slice(16)).eq('project_id',S.project.id);if(r.error)throw r.error;await loadRows();return render()}
 if(code==='delete-dataset'){let ds=S.dataset||S.datasets[0];if(!ds)return;let linked=S.tools.some(t=>t.dataset_id===ds.id||t.content?.dataset_id===ds.id)||S.kpis.some(k=>k.dataset_id===ds.id);if(linked)throw Error('This table is linked to a KPI or method. Remove the references before deleting it; saved analyses must remain reproducible.');if(!confirm('Permanently delete "'+ds.name+'" and its '+S.rows.filter(r=>r.dataset_id===ds.id).length+' observations?'))return;await request('datasets','delete',{id:ds.id});S.dataset=null;await loadProject();return render()}
 if(code==='export-dataset'){let ds=S.dataset||S.datasets[0];return blobDownload(slug(ds.name)+'.csv',csvFromDataset(ds),'text/csv')}
 if(code==='import-new'||code==='import-rows'){let el=document.createElement('input');el.type='file';el.accept='.csv,text/csv';el.onchange=async()=>{try{await importCSV(el.files[0],code==='import-rows'?(S.dataset||S.datasets[0]):null)}catch(e){alert(e.message)}};el.click();return}
 if(code.startsWith('next-action:')){let a=S.actions.find(r=>r.id===code.slice(12));let status=a.status==='todo'?'doing':a.status==='doing'?'done':'todo';await request('actions','update',{id:a.id,data:{status}});await loadProject();return render()}
 if(code.startsWith('download-file:')){let f=S.files.find(r=>r.id===code.slice(14));let {data,error}=await db.storage.from('sigma-studio').createSignedUrl(f.storage_path,60);if(error)throw error;window.open(data.signedUrl,'_blank','noopener');return}
 if(code.startsWith('delete-file:')){let f=S.files.find(r=>r.id===code.slice(12));if(!confirm('Delete this file?'))return;let rr=await db.storage.from('sigma-studio').remove([f.storage_path]);if(rr.error)throw rr.error;await request('files','delete',{id:f.id});await loadProject();return render()}
 if(code==='export-report')return blobDownload(slug(S.project.name)+'-dmaic-report.html',reportHtml(),'text/html');
}
document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-nav]'),act=e.target.closest('[data-act]'),project=e.target.closest('[data-open-project]');
 if(!nav&&!act&&!project)return;
 if(e.target.closest('form')&&e.target.type==='submit')return;
 e.preventDefault();try{if(nav){S.page=nav.dataset.nav;S.tool=null;S.editor=null;S.search='';render()}else if(project)await command('open:'+project.dataset.openProject);else if(act)await command(act.dataset.act)}catch(err){alert('Could not complete action: '+err.message);console.error(err)}
});
document.addEventListener('input',e=>{
 const t=e.target;if(t.dataset.editorField&&S.editor){S.editor.fields??={};S.editor.fields[t.dataset.editorField]=t.value}
 if(t.dataset.editorRow!==undefined&&S.editor){S.editor.rows[Number(t.dataset.editorRow)][t.dataset.editorCol]=t.value}
 if(t.id==='method-search'){S.search=t.value;let pos=t.selectionStart;render();let newEl=$('#method-search');newEl?.focus();newEl?.setSelectionRange(pos,pos)}
});
document.addEventListener('change',async e=>{
 const t=e.target;try{
 if(t.id==='project-switch'){S.project=S.projects.find(p=>p.id===t.value)||null;S.page=S.project?'overview':'projects';S.tool=null;await loadProject();render()}
 if(t.dataset.datasetCell){let row=S.rows.find(r=>r.id===t.dataset.datasetCell),ds=S.datasets.find(d=>d.id===row.dataset_id),column=ds.columns.find(c=>c.key===t.dataset.col);if(!column)throw Error('Column no longer exists.');let value;try{value=parseTypedValue(t.value,column)}catch(e){t.value=row.values[column.key]??'';throw e}let values={...row.values,[column.key]:value};let r=await db.from(A.rows).update({values}).eq('id',row.id).eq('project_id',S.project.id);if(r.error)throw r.error;row.values=values;note('Validated value saved')}
 if(['dataset_id','x','y','order','lsl','usl','opportunities'].includes(t.name)&&S.editor&&S.tool){S.editor[t.name]=t.value;if(t.name==='dataset_id'){S.editor.x='';S.editor.y='';S.editor.order='';render()}}
 }catch(err){alert(err.message)}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['auth-form','project-form','kpi-form','dataset-form','action-form','file-form'].includes(f.id))return;e.preventDefault();if(busy)return;busy=true;let fd=new FormData(f),g=k=>String(fd.get(k)||'').trim();try{
 if(f.id==='auth-form'){let mode=e.submitter?.value||'login',res=mode==='signup'?await db.auth.signUp({email:g('email'),password:g('password')}):await db.auth.signInWithPassword({email:g('email'),password:g('password')});if(res.error)throw res.error;if(!res.data.session){authView('Account created. Check your email for a confirmation link, then sign in.');return}S.user=res.data.user;await refresh();return}
 if(f.id==='project-form'){let payload={name:g('name'),location:g('location'),leader:g('leader'),sponsor:g('sponsor'),methodology:g('methodology'),objective:g('objective')};if(!payload.name)throw Error('Project name required.');if(f.dataset.id){let rr=await db.from(A.projects).update(payload).eq('id',f.dataset.id).select().single();if(rr.error)throw rr.error}else{let rr=await db.from(A.projects).insert(payload).select().single();if(rr.error)throw rr.error;S.project=rr.data}closeModal();S.page='overview';await refresh();return}
 if(f.id==='kpi-form'){let id=f.dataset.id;let payload={project_id:S.project.id,name:g('name'),category:g('category'),unit:g('unit'),direction:g('direction'),source:g('source'),dataset_id:g('dataset_id')||null,value_field:g('value_field'),baseline:g('baseline')===''?null:Number(g('baseline')),target_value:g('target_value')===''?null:Number(g('target_value')),target_high:g('target_high')===''?null:Number(g('target_high'))};if(!payload.name)throw Error('KPI name is required.');if(payload.direction==='range'&&(payload.target_high==null||payload.target_value==null||payload.target_high<payload.target_value))throw Error('Range needs valid lower and upper bounds.');if(id)await request('kpis','update',{id,data:payload});else await request('kpis','insert',payload);closeModal();await loadProject();return render()}
 if(f.id==='dataset-form'){let d=await request('datasets','insert',{project_id:S.project.id,name:g('name'),description:g('description'),columns:[{key:'date',label:'Date',type:'date'},{key:'category',label:'Category',type:'text'},{key:'value',label:'Value',type:'number'}]});S.dataset=d;closeModal();await loadProject();return render()}
 if(f.id==='action-form'){let payload={project_id:S.project.id,title:g('title'),owner_name:g('owner_name'),due_date:g('due_date')||null,phase:g('phase'),status:g('status'),tool_id:g('tool_id')||null,priority:g('priority'),notes:g('notes')};if(!payload.title)throw Error('Action title required.');if(f.dataset.id)await request('actions','update',{id:f.dataset.id,data:payload});else await request('actions','insert',payload);closeModal();await loadProject();return render()}
 if(f.id==='file-form'){let file=fd.get('file');if(!file||!file.size)throw Error('Choose a file.');if(file.size>10485760)throw Error('Files must be under 10 MB.');let path=S.user.id+'/'+S.project.id+'/'+uid()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');let r=await db.storage.from('sigma-studio').upload(path,file,{contentType:file.type||'application/octet-stream'});if(r.error)throw r.error;try{await request('files','insert',{project_id:S.project.id,title:g('title')||file.name,storage_path:path,mime_type:file.type||''})}catch(err){await db.storage.from('sigma-studio').remove([path]);throw err}closeModal();await loadProject();return render()}
 }catch(err){alert('Save failed: '+err.message);console.error(err)}finally{busy=false}
});
async function start(){const {data,error}=await db.auth.getSession();if(error)console.error(error);S.user=data?.session?.user||null;if(!S.user){authView();return}try{await refresh()}catch(e){authView('Database error: '+e.message);console.error(e)}}
db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){S.user=null;S.project=null;authView()}});
start();
